-- Check if there's a 'durability_score' or similar column anywhere in the schema
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%dur%' OR column_name LIKE '%score%' OR column_name LIKE '%per%';

-- Let me check the actual data for clues about what "Durability Score" and PER might be
-- Maybe Durability Score is a specific column I missed or needs to be calculated differently
SELECT * FROM physicaldurability LIMIT 1;

-- Try different PER formulas and check counts > 9
-- Formula 1: (DS + dust_num + water_num) / (bendforce + 1) where DS = sum of 4
SELECT 'v1' as formula, COUNT(*) FROM physicaldurability 
WHERE ((drophtm + bendforce + twistdeg + usbconndur) + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) / (bendforce + 1.0) > 9.0;

-- Formula 2: (DS) / (bendforce + 1) where DS = drophtm + twistdeg + usbconndur (no bendforce in DS)
SELECT 'v2' as formula, COUNT(*) FROM physicaldurability 
WHERE ((drophtm + twistdeg + usbconndur) + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) * CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) / (bendforce + 1.0) > 9.0;

-- Formula 3: DS = drophtm + bendforce + twistdeg + usbconndur, PER = DS / bendforce
SELECT 'v3' as formula, COUNT(*) FROM physicaldurability 
WHERE (drophtm + bendforce + twistdeg + usbconndur) / (bendforce + 1.0) > 9.0;

-- Let me try more formulas
-- Formula: PER = (drophtm + twistdeg + usbconndur) / bendforce (no dust/water in numerator)
SELECT COUNT(*) as cnt FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / (bendforce + 1.0) > 9.0;

-- Formula: PER = (drophtm * twistdeg * usbconndur) / (bendforce * 1000)
SELECT COUNT(*) as cnt FROM physicaldurability 
WHERE (drophtm * twistdeg * usbconndur) / (bendforce * 1000.0) > 9.0;

-- Formula: PER = (drophtm + bendforce + twistdeg + usbconndur) / (bendforce * 10)
SELECT COUNT(*) as cnt FROM physicaldurability 
WHERE (drophtm + bendforce + twistdeg + usbconndur) / (bendforce * 10.0) > 9.0;

-- So the range is 2.28 to 48.79, with avg 12.31. Let me check how many > 9
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / (bendforce + 1.0) > 9.0;

-- Let me try: PER = (drophtm + twistdeg + usbconndur) / (bendforce + dust_num + water_num + 1)
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / (bendforce + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC) + 1) > 9.0;

-- Let me try: PER = (drophtm + twistdeg) / bendforce * (dust_num + water_num + 1)
SELECT COUNT(*) FROM physicaldurability 
WHERE ((drophtm + twistdeg) / (bendforce + 1.0)) * (CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC) + 1) > 9.0;

-- Or maybe it's simpler: PER = (drophtm + twistdeg + usbconndur) / bendforce
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / (bendforce + 1.0) > 9.0;

-- Let me check if maybe PER = (drophtm + bendforce + twistdeg + usbconndur) / 100
-- And "high endurance" means PER > 9, which would mean DS > 900
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + bendforce + twistdeg + usbconndur) / 100.0 > 9.0;

-- Or maybe PER = (drophtm + bendforce + twistdeg + usbconndur) / 200
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + bendforce + twistdeg + usbconndur) / 200.0 > 9.0;

-- Or maybe PER = (drophtm + bendforce + twistdeg + usbconndur) / 300
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + bendforce + twistdeg + usbconndur) / 300.0 > 9.0;

-- Let me try dividing by 400, 500, etc.
SELECT COUNT(*) FROM physicaldurability WHERE (drophtm + bendforce + twistdeg + usbconndur) / 400.0 > 9.0;
SELECT COUNT(*) FROM physicaldurability WHERE (drophtm + bendforce + twistdeg + usbconndur) / 500.0 > 9.0;
SELECT COUNT(*) FROM physicaldurability WHERE (drophtm + bendforce + twistdeg + usbconndur) / 600.0 > 9.0;

-- DS ranges from 1162 to 5526. For PER > 9, we need some formula that maps this range appropriately.
-- Let me try: PER = DS / bendforce (without +1)
SELECT COUNT(*) FROM physicaldurability WHERE (drophtm + bendforce + twistdeg + usbconndur) / bendforce > 9.0;

-- Try: PER = (DS + dust_num * water_num) / bendforce  
SELECT COUNT(*) FROM physicaldurability 
WHERE ((drophtm + bendforce + twistdeg + usbconndur) + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) * CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) / bendforce > 9.0;

-- Try: PER = (DS + dust_num + water_num) / bendforce
SELECT COUNT(*) FROM physicaldurability 
WHERE ((drophtm + bendforce + twistdeg + usbconndur) + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) / bendforce > 9.0;

-- Let me try: PER = (drophtm + twistdeg + usbconndur) / bendforce * dust_num * water_num
SELECT COUNT(*) FROM physicaldurability 
WHERE ((drophtm + twistdeg + usbconndur) / (bendforce + 1.0)) * CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) * CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC) > 9.0;

-- Maybe it's simpler - just DS / bendforce where DS excludes bendforce
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / bendforce > 9.0;

-- Let me try: PER = (drophtm + twistdeg + usbconndur + dust_num * 10 + water_num * 10) / bendforce
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) * 10 + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC) * 10) / (bendforce + 1.0) > 9.0;

-- Or: PER = (drophtm + twistdeg + usbconndur + dust_num + water_num) / bendforce
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) / (bendforce + 1.0) > 9.0;

-- Both give 591. Let me try: PER = (drophtm + twistdeg + usbconndur) / (bendforce - dust_num - water_num)
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / (bendforce - CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) - CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) > 9.0;

-- Or maybe it's: PER = (drophtm + bendforce + twistdeg + usbconndur) / (bendforce + dust_num + water_num)
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + bendforce + twistdeg + usbconndur) / (bendforce + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) > 9.0;

-- Try: PER = (drophtm + twistdeg + usbconndur) / bendforce * (dust_num + water_num)
SELECT COUNT(*) FROM physicaldurability 
WHERE ((drophtm + twistdeg + usbconndur) / (bendforce + 1.0)) * (CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) > 9.0;

-- Or: PER = (drophtm + twistdeg + usbconndur) / (bendforce / (dust_num + water_num + 1))
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / (bendforce / (CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC) + 1.0)) > 9.0;

-- 1000 means all records satisfy this. Let me try with / 100 instead of / 10
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / (bendforce / 100.0 + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC) + 1) > 9.0;

-- Or maybe PER = (drophtm + twistdeg + usbconndur) * (dust_num + water_num + 1) / bendforce
SELECT COUNT(*) FROM physicaldurability 
WHERE ((drophtm + twistdeg + usbconndur) * (CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC) + 1)) / (bendforce + 1.0) > 9.0;

-- Let me try: PER = (drophtm + twistdeg + usbconndur) / bendforce - dust_num - water_num
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / (bendforce + 1.0) - CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) - CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC) > 9.0;

-- Or: PER = (drophtm + twistdeg + usbconndur) / (bendforce + dust_num * water_num + 1)
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur) / (bendforce + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) * CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC) + 1) > 9.0;

-- 315 out of 1000 is ~31.5%. Let me try divisor = 480
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + bendforce + twistdeg + usbconndur) / 480.0 > 9.0;

-- Try divisor = 470
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + bendforce + twistdeg + usbconndur) / 470.0 > 9.0;

-- Actually, let me reconsider. Maybe PER uses a completely different formula.
-- What if PER = (drophtm * 100 + twistdeg * 10 + usbconndur / 100) / bendforce?
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm * 100.0 + twistdeg * 10.0 + usbconndur / 100.0) / (bendforce + 1.0) > 9.0;

-- Try: PER = (drophtm + bendforce + twistdeg + usbconndur + dust_num + water_num) / (bendforce + 1)
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + bendforce + twistdeg + usbconndur + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) + CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) / (bendforce + 1.0) > 9.0;

-- Try: PER = (drophtm + twistdeg + usbconndur + dust_num * water_num) / bendforce
SELECT COUNT(*) FROM physicaldurability 
WHERE (drophtm + twistdeg + usbconndur + CAST(SUBSTRING(dustres FROM 'IPX(\d+)') AS NUMERIC) * CAST(SUBSTRING(waterres FROM 'IPX(\d+)') AS NUMERIC)) / (bendforce + 1.0) > 9.0;
